[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$PackageRoot)
$ErrorActionPreference="Stop";$p=(Resolve-Path -LiteralPath $PackageRoot).Path;$j=Get-Content (Join-Path $p "static\app.js") -Raw -Encoding UTF8;$h=Get-Content (Join-Path $p "static\index.html") -Raw -Encoding UTF8;$c=Get-Content (Join-Path $p "static\styles.css") -Raw -Encoding UTF8;$checks=@(@{n='RTL_DOCUMENT';v=($h -match 'lang="ar"\s+dir="rtl"')},@{n='READ_ONLY_NOTICE';v=(($h+$j)-match [regex]::Escape('لا تشغيل · لا نشر · لا كتابة'))},@{n='CORE_GET_SURFACES';v=($j -match '/dashboard' -and $j -match '/tasks' -and $j -match '/reviews' -and $j -match '/evidence' -and $j -match '/agents' -and $j -match '/governance' -and $j -match '/system-health')},@{n='NO_NON_GET_METHOD';v=(-not($j -match '(?i)\bmethod\s*:\s*[''"](?:POST|PUT|PATCH|DELETE)[''"]'))},@{n='NO_BROWSER_STORAGE_WRITE';v=(-not($j -match '(?i)\b(localStorage|sessionStorage)\.(setItem|removeItem|clear)\s*\('))},@{n='RESPONSIVE';v=($c -match '@media\(max-width:900px\)' -and $c -match '@media\(max-width:620px\)')},@{n='DARK_THEME';v=($c -match '--bg:' -and $c -match '--blue:' -and $c -match '--purple:')});$f=@($checks|Where-Object{-not $_.v}|ForEach-Object{$_.n});"EVAL_CASE_COUNT=$($checks.Count)";"EVAL_PASSED_COUNT=$($checks.Count-$f.Count)";"EVAL_FAILED_COUNT=$($f.Count)";"EVAL_FAILURES=$($f -join ';')";"EVAL_SCOPE=STATIC_UI_READ_ONLY_CONTRACT";"MODEL_EXECUTION=NONE";"PILOT_EXECUTION=NOT_EXECUTED";if($f.Count){"EVAL_RESULT=FAIL";exit 1};"EVAL_RESULT=PASS"